#include <stdio.h>
#include <string.h>
int q[100], front = 0, rear = -1, sz;
void enqueue(int v) { if(rear == sz - 1) printf("Queue is Full\n"); else q[++rear] = v; }
void dequeue() { if(front > rear) printf("Queue is Empty\n"); else printf("%d\n", q[front++]); }
void display() { if(front > rear) printf("Empty\n"); else { for(int i = front; i <= rear; i++) printf("%d%c", q[i], i == rear ? '\n' : ' '); } }
int main() {
    int n, v; char op[20];
    if(scanf("%d %d", &sz, &n) != 2) return 0;
    while(n--) {
        scanf("%s", op);
        if(!strcmp(op, "enqueue")) { scanf("%d", &v); enqueue(v); }
        else if(!strcmp(op, "dequeue")) dequeue();
        else if(!strcmp(op, "display")) display();
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Node { int d; struct Node* n; } Node;
Node *fr = NULL, *re = NULL;
void enqueue(int v) { Node* nn = malloc(sizeof(Node)); nn->d = v; nn->n = NULL; if(re) re->n = nn; else fr = nn; re = nn; }
void dequeue() { if(!fr) { printf("Underflow\n"); return; } Node* t = fr; printf("%d\n", fr->d); fr = fr->n; if(!fr) re = NULL; free(t); }
void peek() { if(!fr) printf("Empty\n"); else printf("%d\n", fr->d); }
void display() { if(!fr) { printf("Empty\n"); return; } Node* t = fr; while(t) { printf("%d%c", t->d, t->n ? ' ' : '\n'); t = t->n; } }
int main() {
    int N, v; char op[20];
    if(scanf("%d", &N) != 1) return 0;
    while(N--) {
        scanf("%s", op);
        if(!strcmp(op, "enqueue")) { scanf("%d", &v); enqueue(v); }
        else if(!strcmp(op, "dequeue")) dequeue();
        else if(!strcmp(op, "front")) peek();
        else if(!strcmp(op, "display")) display();
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
int q[100], front = -1, rear = -1, sz;
void enqueue(int v) {
    if((rear + 1) % sz == front) printf("Queue is Full\n");
    else { if(front == -1) front = 0; rear = (rear + 1) % sz; q[rear] = v; }
}
void dequeue() {
    if(front == -1) printf("Queue is Empty\n");
    else { printf("%d\n", q[front]); if(front == rear) { front = -1; rear = -1; } else front = (front + 1) % sz; }
}
void display() {
    if(front == -1) printf("Empty\n");
    else { int i = front; while(1) { printf("%d%c", q[i], i == rear ? '\n' : ' '); if(i == rear) break; i = (i + 1) % sz; } }
}
int main() {
    int n, v; char op[20];
    if(scanf("%d %d", &sz, &n) != 2) return 0;
    while(n--) {
        scanf("%s", op);
        if(!strcmp(op, "enqueue")) { scanf("%d", &v); enqueue(v); }
        else if(!strcmp(op, "dequeue")) dequeue();
        else if(!strcmp(op, "display")) display();
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
typedef struct Node { int d; struct Node* n; } Node;
Node *fr = NULL, *re = NULL;
void enqueue(int v) { Node* nn = malloc(sizeof(Node)); nn->d = v; if(!fr) { fr = nn; re = nn; nn->n = fr; } else { re->n = nn; re = nn; re->n = fr; } }
void dequeue() { if(!fr) { printf("Underflow\n"); return; } Node* t = fr; printf("%d\n", fr->d); if(fr == re) { fr = NULL; re = NULL; } else { fr = fr->n; re->n = fr; } free(t); }
void display() { if(!fr) { printf("Empty\n"); return; } Node* t = fr; do { printf("%d%c", t->d, t == re ? '\n' : ' '); t = t->n; } while(t != fr); }
int main() {
    int N, v; char op[20];
    if(scanf("%d", &N) != 1) return 0;
    while(N--) {
        scanf("%s", op);
        if(!strcmp(op, "enqueue")) { scanf("%d", &v); enqueue(v); }
        else if(!strcmp(op, "dequeue")) dequeue();
        else if(!strcmp(op, "display")) display();
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
int data[1000], pri[1000], cnt = 0;
void enqueue(int v, int p) { data[cnt] = v; pri[cnt] = p; cnt++; }
void dequeue() {
    if(cnt == 0) { printf("Underflow\n"); return; }
    int idx = 0;
    for(int i = 1; i < cnt; i++) if(pri[i] < pri[idx]) idx = i;
    printf("%d %d\n", data[idx], pri[idx]);
    for(int i = idx; i < cnt - 1; i++) { data[i] = data[i+1]; pri[i] = pri[i+1]; }
    cnt--;
}
void display() {
    if(cnt == 0) { printf("Empty\n"); return; }
    for(int i = 0; i < cnt; i++) printf("%d(%d)%c", data[i], pri[i], i == cnt-1 ? '\n' : ' ');
}
int main() {
    int N, v, p; char op[20];
    if(scanf("%d", &N) != 1) return 0;
    while(N--) {
        scanf("%s", op);
        if(!strcmp(op, "enqueue")) { scanf("%d %d", &v, &p); enqueue(v, p); }
        else if(!strcmp(op, "dequeue")) dequeue();
        else if(!strcmp(op, "display")) display();
    }
    return 0;
}
